class LegacyOrGuardError(RootModel[LegacyError | ApiError]):
    root: LegacyError | ApiError
    """
    A failure on a legacy endpoint comes from one of two places, and they do
    not share a shape: the handler answers with `LegacyError`, while the
    contract guard - which runs before the handler and rejects bad
    parameters, headers and bodies - answers with the `ApiError` envelope
    used everywhere else.

    """


