    """
    How many shelves block the delete (`in_use` / `has_history`).
    """
    blocked_by: Annotated[list[BlockedShelf] | None, Field(max_length=20)] = None
    """
    Up to 20 of the blocking shelves; `blocked_count` tells the whole truth.
    """
    would_delete: TopologyCounts | None = None
    child_counts: TopologyCounts | None = None
    hint: str | None = None
